sys_variable_value.value:
(function() {
    var publisher = new x_1295779_conflu_0.ConfluencePublisher();

    // Get the publishing definition
    var definition = publisher._getDefinition(publishing_definition);
    if (!definition) {
        operation = 'skip';
        cloud_id = '';
        space_id = '';
        page_title = '';
        existing_page_id = '';
        current_version = '';
        parent_page_id = '';
        connection_name = '';
        gs.warn('Get Publishing Context: Definition not found: ' + publishing_definition);
        return;
    }

    // Get connection config
    var config = publisher._getConnectionConfig(definition.connection_config);
    if (!config || !config.cloud_id) {
        operation = 'skip';
        cloud_id = '';
        space_id = '';
        page_title = '';
        existing_page_id = '';
        current_version = '';
        parent_page_id = '';
        connection_name = '';
        gs.warn('Get Publishing Context: Connection config not found or missing cloud_id');
        return;
    }

    cloud_id = config.cloud_id;
    connection_name = config.name || '';

    // Get the source record
    var sourceGr = new GlideRecord(source_table);
    if (!sourceGr.get(source_record_id)) {
        operation = 'skip';
        space_id = '';
        page_title = '';
        existing_page_id = '';
        current_version = '';
        parent_page_id = '';
        gs.warn('Get Publishing Context: Source record not found: ' + source_table + '/' + source_record_id);
        return;
    }

    // Resolve title template
    page_title = publisher._resolveTemplate(definition.title_template, sourceGr);
    parent_page_id = definition.parent_page_id || '';

    // Resolve space key (definition override → config default)
    var spaceKey = definition.target_space_key || config.default_space_key;
    if (!spaceKey) {
        operation = 'skip';
        space_id = '';
        existing_page_id = '';
        current_version = '';
        gs.warn('Get Publishing Context: No space key configured');
        return;
    }

    // Get space ID
    space_id = publisher._getSpaceId(cloud_id, spaceKey, parent_page_id) || '';
    if (!space_id) {
        operation = 'skip';
        existing_page_id = '';
        current_version = '';
        gs.warn('Get Publishing Context: Could not resolve space ID for key: ' + spaceKey);
        return;
    }

    // Determine operation (create/update/skip)
    var opResult = publisher._determineOperation(definition, sourceGr, space_id, page_title, cloud_id);
    operation = opResult.action || 'skip';
    existing_page_id = opResult.pageId || '';
    current_version = opResult.version ? String(opResult.version) : '';
})();

